//! Substring searches over byte slices.
//!
//! The parser works on bytes rather than `str` because C++ `std::string` is a
//! byte string: the reference implementation happily parses an argument that is
//! not valid UTF-8, and reproducing that requires never assuming an encoding.
//! `str::find` is therefore unavailable, so the two searches the parser needs
//! live here.

/// Byte offset of the first occurrence of `needle` in `haystack`.
pub fn find_byte(haystack: &[u8], needle: u8) -> Option<usize> {
    haystack.iter().position(|&b| b == needle)
}

/// Byte offset of the first occurrence of the (non-empty) `needle` slice.
pub fn find_pattern(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.len() > haystack.len() {
        return None;
    }
    haystack
        .windows(needle.len())
        .position(|window| window == needle)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn finds_first_occurrence_only() {
        assert_eq!(find_byte(b"a:b:c", b':'), Some(1));
        assert_eq!(find_byte(b"abc", b':'), None);
        assert_eq!(find_pattern(b"a://b://c", b"://"), Some(1));
        assert_eq!(find_pattern(b"a:/b", b"://"), None);
        assert_eq!(find_pattern(b"://", b"://"), Some(0));
        assert_eq!(find_pattern(b":/", b"://"), None);
    }

    #[test]
    fn tolerates_non_utf8_bytes() {
        assert_eq!(find_byte(b"\xff\xfe:", b':'), Some(2));
        assert_eq!(find_pattern(b"\xf8://x", b"://"), Some(1));
    }
}
